G[22]=[
{t:"Mệnh đề định ngữ",m:"Câu bổ nghĩa cho danh từ",e:"Câu thể thông thường đặt ngay trước danh từ để bổ nghĩa. Riêng với hiện tại khẳng định: tính từ な giữ な (～な N), danh từ dùng の (～の N). Trật tự ngược với tiếng Việt: “cái bánh mà chị Maria làm” = マリアさんが つくった ケーキ.",x:[["これは ミラーさんが すんで いた うちです。","Đây là ngôi nhà anh Miller từng sống."],["カリナさんが かいた え","bức tranh Karina vẽ"],["あした こない ひと","người mai không đến"]]},
{t:"Chủ ngữ trong mệnh đề định ngữ dùng が",m:"が thay cho は",e:"Chủ thể của hành động trong mệnh đề định ngữ đi với が, vì đó không phải chủ đề của cả câu.",x:[["わたしは マリアさんが つくった ケーキが すきです。","Tôi thích bánh Maria làm."]]},
{t:"Danh từ có định ngữ trong câu",m:"Dùng như danh từ thường",e:"Cụm “định ngữ + N” có thể làm chủ đề, tân ngữ, bổ ngữ… với đủ loại trợ từ.",x:[["ミラーさんが すんで いた うちは ふるいです。","Ngôi nhà anh Miller từng sống thì cũ."],["ミラーさんが すんで いた うちを かいました。","Tôi mua ngôi nhà anh Miller từng sống."]]},
{t:"V る ＋ じかん / やくそく / ようじ",m:"Thời gian / hẹn / việc để làm V",e:"Thể từ điển bổ nghĩa cho các danh từ này để nói nội dung.",x:[["あさごはんを たべる じかんが ありません。","Tôi không có thời gian ăn sáng."],["ともだちと えいがを みる やくそくが あります。","Tôi có hẹn đi xem phim với bạn."]]}];
G[23]=[
{t:"～とき、～",m:"Khi…",e:"とき là danh từ nên nối giống định ngữ: V thường/thể ない + とき; Aい + とき; Aな + な + とき; N + の + とき.",x:[["としょかんで ほんを かりる とき、カードが いります。","Khi mượn sách ở thư viện cần thẻ."],["ひまな とき、あそびに きて ください。","Khi rảnh hãy đến chơi."],["こどもの とき、よく かわで およぎました。","Hồi nhỏ tôi hay bơi ở sông."]]},
{t:"V る とき vs V た とき",m:"Trước / sau khi hành động hoàn tất",e:"V る とき: hành động ở mệnh đề chính xảy ra trước khi V hoàn tất. V た とき: xảy ra sau khi V đã hoàn tất.",x:[["くにへ かえる とき、かばんを かいました。","Lúc (chuẩn bị) về nước, tôi mua cặp (mua ở Nhật)."],["くにへ かえった とき、かばんを かいました。","Khi đã về nước, tôi mua cặp (mua ở quê)."]]},
{t:"V る と、～",m:"Hễ… thì…",e:"Kết quả tất yếu, tự nhiên xảy ra (cách dùng máy móc, chỉ đường, quy luật). Vế sau không dùng để diễn đạt ý chí, mong muốn, lời mời, nhờ vả.",x:[["この ボタンを おすと、おつりが でます。","Ấn nút này thì tiền thừa sẽ ra."],["まっすぐ いくと、みぎに ぎんこうが あります。","Đi thẳng thì bên phải có ngân hàng."]]},
{t:"N が A / V（miêu tả trạng thái）",m:"Chủ thể + が",e:"Miêu tả hiện trạng, cảnh tượng như vốn có thì chủ thể dùng が.",x:[["おとが ちいさいです。","Âm thanh nhỏ."],["でんきが あかるく なりました。","Đèn sáng hơn rồi."]]},
{t:"N（địa điểm）を V（di chuyển）",m:"Đi qua / dọc theo N",e:"を chỉ nơi chốn mà sự di chuyển đi qua: さんぽします, わたります, あるきます, まがります.",x:[["こうえんを さんぽします。","Đi dạo trong công viên."],["はしを わたります。","Đi qua cầu."],["こうさてんを みぎへ まがります。","Rẽ phải ở ngã tư."]]}];
V[24]=[["くれます","","cho, tặng (tôi)"],["なおします","直します","sửa, chữa"],["つれて いきます","連れて行きます","dẫn (ai) đi"],["つれて きます","連れて来ます","dẫn (ai) đến"],["おくります［ひとを～］","送ります［人を～］","tiễn, đưa [người]"],["しょうかいします","紹介します","giới thiệu"],["あんないします","案内します","hướng dẫn, dẫn đường"],["せつめいします","説明します","giải thích"],["いれます［コーヒーを～］","","pha [cà phê]"],["おじいさん／おじいちゃん","","ông"],["おばあさん／おばあちゃん","","bà"],["じゅんび","準備","chuẩn bị"],["いみ","意味","ý nghĩa"],["［お］かし","［お］菓子","bánh kẹo"],["ぜんぶ","全部","toàn bộ"],["じぶんで","自分で","tự mình"],["ほかに","","ngoài ra"],["ワゴンしゃ","ワゴン車","xe tải nhỏ (van)"],["［お］べんとう","［お］弁当","cơm hộp"],["ははの ひ","母の日","Ngày của Mẹ"]];
V[25]=[["かんがえます","考えます","suy nghĩ"],["つきます［えきに～］","着きます［駅に～］","đến [ga]"],["とります［としを～］","取ります［年を～］","thêm [tuổi], già đi"],["たります","足ります","đủ"],["いなか","田舎","quê, nông thôn"],["チャンス","","cơ hội"],["おく","億","một trăm triệu"],["もし［～たら］","","nếu"],["いくら［～ても］","","cho dù… thế nào"],["てんきん","転勤","chuyển công tác"],["こと","","việc"],["いっぱい のみましょう","一杯飲みましょう","cùng làm một chén nhé"],["［いろいろ］おせわに なりました","［いろいろ］お世話になりました","cảm ơn đã giúp đỡ [nhiều]"],["がんばります","頑張ります","cố gắng"],["どうぞ おげんきで","どうぞ お元気で","chúc anh/chị mạnh khỏe"],["たいしかん","大使館","đại sứ quán"],["グループ","","nhóm"]];
G[24]=[
{t:"くれます",m:"(Ai đó) cho tôi",e:"Khi người nhận là “tôi” (hoặc người nhà mình), dùng くれます thay cho あげます. わたしに thường được lược bỏ. Tổng kết: あげます (cho người khác), もらいます (nhận), くれます (người khác cho tôi).",x:[["さとうさんは わたしに クリスマスカードを くれました。","Chị Sato tặng tôi thiệp Giáng sinh."]]},
{t:"V て あげます",m:"Làm V cho (người khác)",e:"Làm một việc vì người khác với thiện ý. Không dùng với người trên hoặc người không thân vì có thể nghe như kẻ cả; khi đó dùng V ましょうか.",x:[["わたしは きむらさんに ほんを かして あげました。","Tôi cho chị Kimura mượn sách."]]},
{t:"V て もらいます",m:"Được (ai) làm V cho",e:"Đứng ở góc nhìn người nhận, thể hiện lòng biết ơn. Người làm hành động + に.",x:[["わたしは やまださんに としょかんの でんわばんごうを おしえて もらいました。","Tôi được anh Yamada cho biết số điện thoại thư viện."]]},
{t:"V て くれます",m:"(Ai đó) làm V cho tôi",e:"Người khác làm việc gì đó cho mình, thể hiện biết ơn. Chủ ngữ là người làm hành động.",x:[["ははは わたしに セーターを おくって くれました。","Mẹ đã gửi áo len cho tôi."]]},
{t:"N（người）が V",m:"Chủ ngữ là thông tin mới",e:"Khi giới thiệu thông tin mới về một chủ đề vừa được nhắc tới, chủ ngữ dùng が.",x:[["すてきな ネクタイですね。…ええ、さとうさんが くれました。","Cà vạt đẹp nhỉ. – Vâng, chị Sato tặng đấy."]]},
{t:"Từ hỏi が V",m:"Ai/cái gì làm V?",e:"Từ để hỏi làm chủ ngữ luôn đi với が, kể cả trong câu động từ.",x:[["だれが てつだいに いきますか。…カリナさんが いきます。","Ai đi giúp? – Karina đi."]]}];
G[25]=[
{t:"Thể quá khứ thông thường ＋ ら（～たら）",m:"Nếu…",e:"Điều kiện giả định. Vế sau có thể là ý chí, mong muốn, lời mời, nhờ vả. V た→たら; Aい→かったら; Aな/N→だったら; phủ định ～なかったら.",x:[["おかねが あったら、りょこうします。","Nếu có tiền tôi sẽ đi du lịch."],["いみが わからなかったら、じしょを しらべて ください。","Nếu không hiểu nghĩa hãy tra từ điển."],["ひまだったら、てつだって ください。","Nếu rảnh thì giúp tôi với."]]},
{t:"V た ら、～（điều chắc chắn xảy ra）",m:"Sau khi / khi… thì",e:"Hành động ở vế sau sẽ làm sau khi vế trước (chắc chắn sẽ xảy ra) hoàn tất. Không mang nghĩa giả định; vế sau ở thì hiện tại/tương lai.",x:[["10じに なったら、でかけましょう。","Đến 10 giờ thì ta ra ngoài."],["うちへ かえったら、すぐ シャワーを あびます。","Về đến nhà tôi tắm ngay."]]},
{t:"～たら vs ～と",m:"So sánh",e:"と: kết quả tất yếu, điều kiện chung; vế sau không chứa ý chí. たら: dùng được cả cho giả định và vế sau có ý chí, mời mọc. Chỗ nào dùng được と thì thường cũng dùng được たら, nhưng không ngược lại.",x:[["じかんが あったら、えいがを みに いきましょう。（○）","Nếu có thời gian ta đi xem phim nhé."]]},
{t:"V て も / Aい くても / Aな・N でも",m:"Dù… cũng…",e:"Điều kiện nghịch: kết quả trái với điều thông thường hoặc mong đợi.",x:[["あめが ふっても、せんたくします。","Dù mưa tôi vẫn giặt đồ."],["やすくても、グループりょこうは きらいです。","Dù rẻ tôi vẫn ghét đi tour."],["にちようびでも、はたらきます。","Dù là Chủ nhật tôi vẫn làm việc."]]},
{t:"もし ～たら / いくら ～ても",m:"Nếu như… / Dù… thế nào đi nữa",e:"もし nhấn mạnh tính giả định; いくら nhấn mạnh mức độ của điều kiện nghịch.",x:[["もし 1おくえん あったら、いろいろな くにを りょこうしたいです。","Nếu có 100 triệu yên tôi muốn đi du lịch nhiều nước."],["いくら かんがえても、わかりません。","Nghĩ thế nào cũng không hiểu."]]},
{t:"Chủ ngữ của mệnh đề phụ dùng が",m:"～が ＋ たら / ても / とき / と / まえに / から",e:"Trong mệnh đề phụ, chủ ngữ đi với が chứ không phải は.",x:[["ともだちが くる まえに、へやを そうじします。","Trước khi bạn đến, tôi dọn phòng."],["やまださんが こなかったら、どうしますか。","Nếu anh Yamada không đến thì làm sao?"]]}];
