const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const store={get(k,d){try{const v=localStorage.getItem(k);return v==null?d:JSON.parse(v)}catch(e){return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}};
let S={tab:store.get("mn.tab","g"),lesson:store.get("mn.lesson",0),q:"",hideVi:false,hideMean:false,hideKana:false,mode:"list",known:store.get("mn.known",{}),deck:[],i:0};
const norm=s=>String(s).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/đ/g,"d");
function hl(text,q){const t=esc(text);if(!q)return t;const n=norm(text);const qq=norm(q);const at=n.indexOf(qq);if(at<0)return t;
  return esc(text.slice(0,at))+"<mark>"+esc(text.slice(at,at+q.length))+"</mark>"+esc(text.slice(at+q.length));}
const lessonsShown=()=>S.lesson?[S.lesson]:Array.from({length:25},(_,i)=>i+1);

function chips(){const el=$("#lessons");let h=`<button class="chip" data-l="0" aria-pressed="${S.lesson===0}">Tất cả</button>`;
  for(let i=1;i<=25;i++)h+=`<button class="chip" data-l="${i}" aria-pressed="${S.lesson===i}">${i}</button>`;el.innerHTML=h;}
function tabs(){$("#t-g").setAttribute("aria-selected",S.tab==="g");$("#t-v").setAttribute("aria-selected",S.tab==="v");}

function renderG(){const q=S.q.trim();let out=`<div class="study"><button class="tg" id="hv" aria-pressed="${S.hideVi}">Che bản dịch ví dụ</button><span class="count" id="cnt"></span></div>`;let n=0;
  for(const l of lessonsShown()){const items=G[l].filter(g=>!q||norm(g.t+" "+g.m+" "+g.e+" "+g.x.flat().join(" ")).includes(norm(q)));if(!items.length)continue;n+=items.length;
    out+=`<section class="lesson" id="g${l}"><div class="stamp"><b>${l}</b><span>Bài</span></div><div class="sheet">`;
    for(const g of items){out+=`<article class="gp"><h3>${hl(g.t,q)}</h3><p class="m">${hl(g.m,q)}</p><p class="e">${hl(g.e,q)}</p>`;
      if(g.x.length){out+=`<ul class="ex">`+g.x.map(x=>`<li><span class="j">${hl(x[0],q)}</span><span class="v">${hl(x[1],q)}</span></li>`).join("")+`</ul>`}out+=`</article>`}
    out+=`</div></section>`}
  if(!n)out+=`<p class="empty">Không có mẫu ngữ pháp nào khớp “${esc(q)}”. Thử từ khóa khác hoặc chọn “Tất cả”.</p>`;
  $("#main").innerHTML=out;$("#cnt").textContent=n+" mẫu ngữ pháp";document.body.classList.toggle("hide-vi",S.hideVi);}

function words(){const q=S.q.trim();const r=[];for(const l of lessonsShown())V[l].forEach((w,i)=>{if(!q||norm(w.join(" ")).includes(norm(q)))r.push({l,i,w})});return r;}
function renderV(){const list=words();const known=list.filter(o=>S.known[o.l+"-"+o.i]).length;
  let out=`<div class="study">
   <button class="tg" data-m="list" aria-pressed="${S.mode==="list"}">Bảng từ</button>
   <button class="tg" data-m="card" aria-pressed="${S.mode==="card"}">Thẻ ghi nhớ</button>
   ${S.mode==="list"?`<button class="tg" id="hm" aria-pressed="${S.hideMean}">Che nghĩa</button><button class="tg" id="hk" aria-pressed="${S.hideKana}">Che cách đọc</button>`:""}
   <span class="count">${list.length} từ · đã thuộc ${known}</span></div>`;
  if(!list.length){$("#main").innerHTML=out+`<p class="empty">Không có từ nào khớp “${esc(S.q)}”. Thử gõ không dấu hoặc bằng hiragana.</p>`;return}
  if(S.mode==="list"){const q=S.q.trim();
    for(const l of lessonsShown()){const ws=list.filter(o=>o.l===l);if(!ws.length)continue;
      out+=`<section class="lesson" id="v${l}"><div class="stamp"><b>${l}</b><span>Bài</span></div><div class="sheet wrap"><table class="vt"><thead><tr><th class="n">#</th><th>Từ</th><th class="h">Hán tự</th><th>Nghĩa</th><th aria-label="Đã thuộc"></th></tr></thead><tbody>`;
      for(const o of ws){const id=o.l+"-"+o.i,[k,h,m]=o.w;
        out+=`<tr class="${S.known[id]?"known":""}"><td class="n">${o.i+1}</td><td class="k kana c">${hl(k,q)}</td><td class="h">${hl(h,q)}</td><td class="mean c">${hl(m,q)}</td><td><button class="mk" data-id="${id}" aria-label="Đánh dấu đã thuộc">✓</button></td></tr>`}
      out+=`</tbody></table></div></section>`}
    $("#main").innerHTML=out;document.body.classList.toggle("hide-mean",S.hideMean);document.body.classList.toggle("hide-kana",S.hideKana);
  }else{if(!S.deck.length||S.deckKey!==deckKey()){S.deck=list.filter(o=>!S.known[o.l+"-"+o.i]);if(!S.deck.length)S.deck=list.slice();S.i=0;S.deckKey=deckKey()}
    const o=S.deck[S.i%S.deck.length],[k,h,m]=o.w;
    out+=`<div class="fc"><div class="card" id="card" tabindex="0" role="button" aria-label="Lật thẻ"><div class="inner">
      <div class="face"><span class="tag">Bài ${o.l} · ${S.i%S.deck.length+1}/${S.deck.length}</span><div class="big">${esc(h||k)}</div>${h?`<div class="sub" style="visibility:hidden">${esc(k)}</div>`:""}<p style="color:var(--muted);font-size:13px;margin-top:18px">Chạm để xem nghĩa</p></div>
      <div class="face back"><span class="tag">Bài ${o.l}</span><div class="big">${esc(k)}</div>${h?`<div class="sub">${esc(h)}</div>`:""}<div class="mean">${esc(m)}</div></div>
    </div></div><div class="fnav"><button class="btn" id="prev">Trước</button><button class="btn" id="shuf">Xáo thẻ</button><button class="btn good" id="got">Đã thuộc</button><button class="btn pri" id="next">Tiếp</button></div></div>`;
    $("#main").innerHTML=out;}
}
const deckKey=()=>S.lesson+"|"+S.q;
function render(){tabs();chips();S.tab==="g"?renderG():renderV();store.set("mn.tab",S.tab);store.set("mn.lesson",S.lesson);}

document.addEventListener("click",e=>{const t=e.target.closest("button,td.c,.ex .v,#card");if(!t)return;
  if(t.id==="t-g"){S.tab="g";render();scrollTo(0,0)}else if(t.id==="t-v"){S.tab="v";render();scrollTo(0,0)}
  else if(t.dataset.l!=null&&t.classList.contains("chip")){S.lesson=+t.dataset.l;S.deck=[];render();scrollTo(0,0)}
  else if(t.id==="hv"){S.hideVi=!S.hideVi;render()}
  else if(t.id==="hm"){S.hideMean=!S.hideMean;render()}
  else if(t.id==="hk"){S.hideKana=!S.hideKana;render()}
  else if(t.dataset.m){S.mode=t.dataset.m;render()}
  else if(t.classList.contains("mk")){const id=t.dataset.id;S.known[id]?delete S.known[id]:S.known[id]=1;store.set("mn.known",S.known);t.closest("tr").classList.toggle("known");renderCount()}
  else if(t.matches("td.c")||t.matches(".ex .v")){t.classList.toggle("show")}
  else if(t.id==="card"){t.classList.toggle("flip")}
  else if(t.id==="next"){S.i=(S.i+1)%S.deck.length;renderV()}
  else if(t.id==="prev"){S.i=(S.i-1+S.deck.length)%S.deck.length;renderV()}
  else if(t.id==="shuf"){for(let i=S.deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[S.deck[i],S.deck[j]]=[S.deck[j],S.deck[i]]}S.i=0;renderV()}
  else if(t.id==="got"){const o=S.deck[S.i];S.known[o.l+"-"+o.i]=1;store.set("mn.known",S.known);S.deck.splice(S.i,1);if(!S.deck.length){S.deck=[];}else S.i%=S.deck.length;renderV()}
  else if(t.id==="theme"){const r=document.documentElement;const dark=r.dataset.theme?r.dataset.theme==="dark":matchMedia("(prefers-color-scheme:dark)").matches;r.dataset.theme=dark?"light":"dark";store.set("mn.theme",r.dataset.theme)}
});
function renderCount(){const c=document.querySelector(".count");if(!c)return;const list=words();c.textContent=list.length+" từ · đã thuộc "+list.filter(o=>S.known[o.l+"-"+o.i]).length}
document.addEventListener("keydown",e=>{if(S.tab!=="v"||S.mode!=="card"||e.target.id==="q")return;
  if(e.key===" "||e.key==="Enter"){const c=$("#card");if(c){e.preventDefault();c.classList.toggle("flip")}}
  if(e.key==="ArrowRight")$("#next")?.click();if(e.key==="ArrowLeft")$("#prev")?.click();});
let tm;$("#q").addEventListener("input",e=>{clearTimeout(tm);tm=setTimeout(()=>{S.q=e.target.value;S.deck=[];S.tab==="g"?renderG():renderV()},150)});
const th=store.get("mn.theme",null);if(th)document.documentElement.dataset.theme=th;
render();
